<script setup lang="ts">
const {transactions,totalFees}=useTransactions(); const {openFile}=useFileStore(); const q=ref(''),from=ref(''),to=ref('')
const archived=computed(()=>transactions.value.filter(t=>t.stages.find(s=>s.key==='archive')?.status==='done').filter(t=>{const d=t.createdAt.slice(0,10),hay=[t.serial,t.companyName,t.driverName,t.vehicleNumber,t.declarationNo,t.manifestNo,t.unifiedProcedureNo].join(' ').toLowerCase();return (!q.value||hay.includes(q.value.toLowerCase()))&&(!from.value||d>=from.value)&&(!to.value||d<=to.value)}))
const total=computed(()=>archived.value.reduce((s,t)=>s+totalFees(t),0)); function fmt(n:number){return new Intl.NumberFormat('ar-IQ').format(n)}
</script>
<template><div class="page-head"><div><h1>الأرشيف</h1><p>المعاملات المؤرشفة وملفاتها النهائية</p></div></div><div class="grid stats"><div class="stat"><small>عدد النتائج</small><strong>{{archived.length}}</strong></div><div class="stat"><small>إجمالي النتائج</small><strong>{{fmt(total)}} د.ع</strong></div></div><div class="card"><div class="filters"><input v-model="q" class="input" placeholder="بحث في الأرشيف" style="min-width:280px"><input v-model="from" type="date" class="input"><input v-model="to" type="date" class="input"></div><div class="table-wrap"><table class="table"><thead><tr><th>المعاملة</th><th>التاريخ</th><th>الشركة</th><th>السيارة</th><th>البيان</th><th>المانيفست</th><th>الرسوم</th><th>الملف النهائي</th></tr></thead><tbody><tr v-for="t in archived" :key="t.id"><td><NuxtLink class="link" :to="`/transactions/${t.id}`">{{t.serial}}</NuxtLink></td><td>{{new Date(t.createdAt).toLocaleDateString('ar-IQ')}}</td><td>{{t.companyName}}</td><td>{{t.vehicleNumber}}</td><td>{{t.declarationNo||'—'}}</td><td>{{t.manifestNo||'—'}}</td><td>{{fmt(totalFees(t))}}</td><td><button v-if="t.attachments.find(a=>a.category==='final')" class="btn ghost" @click="openFile(t.attachments.find(a=>a.category==='final')!.id)">فتح PDF</button><span v-else>—</span></td></tr><tr v-if="!archived.length"><td colspan="8" class="empty">لا توجد معاملات مؤرشفة ضمن البحث</td></tr></tbody></table></div></div></template>
